style.css:
@-moz-document domain("open.spotify.com") {
/* BACKGROUND WALLPAPER */
body {
    background:
        linear-gradient(
            rgba(0,0,0,0.30),
            rgba(0,0,0,0.48)
        ),
        url("https://i.postimg.cc/0ym9Tq1j/0adbe015f2b7f0123d34ad32970f23bf.jpg")
        center center / cover fixed no-repeat !important;
}

/* MAIN CONTENT */
.main-view-container,
.main-view-container__scroll-node,
.main-view-container__scroll-node-child,
.Root__main-view {
    background: transparent !important;
}

/* SIDEBAR */
.Root__nav-bar,
.main-nav-bar {
    background: rgba(12,12,12,0.82) !important;
    backdrop-filter: blur(18px) !important;
    border: 1px solid rgba(255,255,255,0.08) !important;
}

/* MUSIC PLAYER */
.Root__now-playing-bar {
    background: rgba(8,8,8,0.92) !important;
    backdrop-filter: blur(20px) !important;
    border-top: 1px solid rgba(255,255,255,0.12) !important;
}

/* TEXT */
body,
h1, h2, h3, h4,
.main-trackList-trackListHeader,
.main-trackList-trackListRow {
    color: #eeeeee !important;
}

/* SECONDARY TEXT */
.main-type-mesto,
.main-type-ballad {
    color: #bcbcbc !important;
}

/* ICONS */
svg {
    color: #eeeeee !important;
    fill: currentColor;
}

/* ICON BUTTONS */
button svg,
nav svg {
    color: #eeeeee !important;
}

/* PLAY BUTTON */
button[data-testid="play-button"] {
    background: #eeeeee !important;
    color: #080808 !important;
    border-radius: 50% !important;
}

/* CARDS */
[data-testid="card"],
.main-card-container {
    background: rgba(10,10,10,0.60) !important;
    backdrop-filter: blur(12px) !important;
    border: 1px solid rgba(255,255,255,0.07) !important;
    border-radius: 12px !important;
}

/* HOVER EFFECT */
[data-testid="card"]:hover {
    background: rgba(35,35,35,0.85) !important;
    transition: 0.3s ease !important;
}

/* SEARCH BAR */
input,
[data-testid="search-input"] {
    background: rgba(15,15,15,0.85) !important;
    color: white !important;
    border: 1px solid rgba(255,255,255,0.15) !important;
}

/* PLAYBACK PROGRESS */
.progress-bar__fg {
    background: #eeeeee !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 5px;
}

::-webkit-scrollbar-thumb {
    background: #777777 !important;
    border-radius: 20px;
}

::-webkit-scrollbar-track {
    background: transparent !important;
}

/* REMOVE BRIGHT BACKGROUNDS */
.main-view-container,
.Root__main-view,
.main-home-content {
    background-color: transparent !important;
}
}
